(window.LADDER_CARDS=window.LADDER_CARDS||{})["25·chem"]=[{"q": "A change A ⇌ B runs α to β at k_f a and back at k_r b. What is b*/a* at rest?", "a": "k_f/k_r", "w": ["k_r/k_f", "k_f k_r", "k_f + k_r"], "why": "The balance technique: equal paces at rest."}, {"q": "A mixture has stopped changing. What are its molecules doing?", "a": "still changing, as fast one way as the other", "w": ["nothing", "only the forward change", "only the reverse change"], "why": "A crowd at rest is not a crowd of things at rest."}, {"q": "The ratio’s polynomial has roots 2.326 and 0.934, and x must lie in [0, 1). Which is the answer?", "a": "0.934", "w": ["2.326", "both", "their average"], "why": "The window technique."}, {"q": "Why is there exactly one root in the window?", "a": "the ratio Q only climbs, from 0 past every ceiling", "w": ["polynomials have one root", "K is positive", "the quadratic formula gives one"], "why": "The in-between value technique, and Q rising."}, {"q": "A cubic for the amounts at rest has one real root. What are its other two?", "a": "a flipped pair off the line", "w": ["two more real roots", "none", "the same root twice"], "why": "Roots in pairs (25e)."}, {"q": "Q is greater than K. Which way does the mixture run?", "a": "back, toward the starting stuff", "w": ["forward", "neither", "it explodes"], "why": "The push-back technique: forward/reverse = K/Q."}, {"q": "Two changes in a row add to one change. What happens to their Ks?", "a": "they multiply", "w": ["they add", "the larger wins", "they average"], "why": "Q of the sum is the product of the Qs."}, {"q": "What is ΔG°, in terms of K?", "a": "−RT ln K", "w": ["RT ln K", "−K/RT", "−RT K"], "why": "The rest-energy technique: at rest ΔG = 0 and Q = K."}, {"q": "ΔG° of a change is positive. What can you conclude?", "a": "K is below 1", "w": ["nothing forms", "K is 0", "the change runs backwards to the end"], "why": "K = e^(−ΔG°/RT), positive and less than 1."}, {"q": "In a cold flask where nothing runs back, what sets the ratio of two products?", "a": "their paces", "w": ["their energies", "their Ks", "their masses"], "why": "The control technique."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["27·chem"]=[{"q": "C: 3x₁ = x₃ for C₃H₈ + O₂ → CO₂ + H₂O. What is that line?", "a": "the carbon sameness", "w": ["the oxygen sameness", "the charge sameness", "the balance"], "why": "One sameness per element: count C on both sides."}, {"q": "The balances of a reaction are exactly …", "a": "what its atom grid sends to zero", "w": ["what its atom grid reaches", "its atom grid’s columns", "the stretches of its atom grid"], "why": "The atom-grid technique: Ax = 0."}, {"q": "Two balances of one reaction, added. The result is …", "a": "a balance", "w": ["never a balance", "a balance only if equal", "a balance of a new reaction"], "why": "What a straight map loses is a space of vectors."}, {"q": "An atom grid with 4 species reaches a space of dimension 3. The balances form …", "a": "a space of dimension 1", "w": ["a space of dimension 3", "only the zero list", "a space of dimension 4"], "why": "Lost plus reached: 1 + 3 = 4. One up to scale."}, {"q": "C₃H₈ + 5O₂ → 3CO₂ + 4H₂O. Is (2, 10, 6, 8) a balance?", "a": "yes, a stretch of (1, 5, 3, 4)", "w": ["no, not least whole", "no, the O count is off", "yes, a different reaction"], "why": "Balances stretch; least whole numbers is one choice."}, {"q": "Ions take part. The extra row of the grid keeps …", "a": "the charge", "w": ["the mass", "the energy", "the number of molecules"], "why": "Charges on the left equal charges on the right."}, {"q": "C + O₂ → CO + CO₂ has balances of dimension 2. What fixes the mix?", "a": "the fire: heat and air", "w": ["the atoms alone", "elimination", "the least whole numbers"], "why": "The many-ways technique: counting atoms cannot fix proportions."}, {"q": "H₂O₂ → H₂O. The grid loses only 0. So …", "a": "a species is missing", "w": ["the reaction is balanced", "the grid has dimension 1", "the amounts are fractions"], "why": "The missing-species technique: the fizz is O₂."}, {"q": "CaO → CaCO₃ + CO₂ has the balance (1, 1, −1). It means …", "a": "CO₂ belongs on the left", "w": ["no balance exists", "CaO is missing", "the reaction runs at −1 speed"], "why": "The wrong-side technique: move the negative species across."}, {"q": "N₂ + 4H₂ → 2NH₄ balances the atoms. So the reaction …", "a": "may still not happen", "w": ["must happen", "is impossible", "has many balances"], "why": "A balance is needed, not enough; NH₄ alone is no molecule."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["32·chem"]=[{"q": "Cells are cubes of side L. Which turnings repeat with the crystal?", "a": "e^(2πi(hx + ky + lz)/L), h, k, l whole", "w": ["e^(2πi(x + y + z)/L)", "sin(hx) sin(ky) sin(lz)", "e^(i(h + k + l))"], "why": "One for each triple of whole numbers."}, {"q": "What is the spacing of the planes of (h, k, l)?", "a": "L/√(h² + k² + l²)", "w": ["L(h + k + l)", "L/(h + k + l)", "L√(h² + k² + l²)"], "why": "The turning is constant on those planes."}, {"q": "2e sin θ = λ. Which technique?", "a": "spot-condition", "w": ["cell-sum", "line-width", "samples-are-coefficients"], "why": "The cells agree only when q is a turning of the crystal."}, {"q": "In 2e sin θ = λ, what is 2θ?", "a": "the angle the ray is turned through", "w": ["the angle of the planes", "the angle of the screen", "twice the wavelength"], "why": "θ is half the turn of the ray."}, {"q": "F_hkl = Σ fⱼ e^(−2πi(hxⱼ + kyⱼ + lzⱼ)). Which technique?", "a": "cell-sum", "w": ["spot-condition", "turning-shadow", "blend-coefficients"], "why": "One cell’s atoms, each with its turning."}, {"q": "Salt, (1, 0, 0): what is F?", "a": "0", "w": ["4f_Na + 4f_Cl", "4f_Na − 4f_Cl", "f_Na"], "why": "Mixed odd and even: the cell cancels itself."}, {"q": "Salt, (1, 1, 1): what is F?", "a": "4f_Na − 4f_Cl", "w": ["4f_Na + 4f_Cl", "0", "8f_Na"], "why": "Each Cl place gives the turn −1."}, {"q": "Salt’s (2, 0, 0) spot gives d = 2.82 Å. What is L?", "a": "5.64 Å", "w": ["2.82 Å", "1.41 Å", "3.99 Å"], "why": "d = L/2."}, {"q": "The brightness of a spot gives F_hkl. Is the move allowed?", "a": "no: it gives |F|², the turn is lost", "w": ["yes: by cell-sum", "yes: up to a sign", "only for salt"], "why": "Same size, different turns, same spot."}, {"q": "The spots are a picture of the atoms. Is the move allowed?", "a": "no: they are sizes of coefficients", "w": ["yes: magnified", "yes: by spot-condition", "only for cubic cells"], "why": "A spot is a coefficient made visible."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["35·chem"]=[{"q": "The turning lines of a molecule of two atoms are how far apart?", "a": "2B", "w": ["B", "B/2", "4B"], "why": "E_(J+1) − E_J = 2hB(J + 1)."}, {"q": "Carbon monoxide’s J = 0 to 1 line is at 115.271 GHz. What is B?", "a": "57.636 GHz", "w": ["115.271 GHz", "230.54 GHz", "28.82 GHz"], "why": "The first line is 2B."}, {"q": "What bond length does that line give for CO?", "a": "about 0.113 nm", "w": ["about 1.13 nm", "about 0.0113 nm", "about 0.529 nm"], "why": "r = √(I/μ)."}, {"q": "HCl shakes at 2886 cm⁻¹. What stiffness does that give?", "a": "about 481 N/m", "w": ["about 48 N/m", "about 4810 N/m", "about 2886 N/m"], "why": "κ = μ(2πcν̃)²."}, {"q": "Swap HCl’s hydrogen for its heavy twin. The shake?", "a": "lower: about 2070 cm⁻¹", "w": ["higher", "the same", "doubled"], "why": "Same κ, larger μ."}, {"q": "Does a heavier isotope make a stiffer bond?", "a": "no: only μ changes", "w": ["yes", "only for hydrogen", "yes, twice as stiff"], "why": "The move to watch out for in 35·chem.5."}, {"q": "Why is there a gap at the middle of an infrared band?", "a": "J may not stay put", "w": ["the bond breaks there", "the light is too weak", "B is zero there"], "why": "One lump changes J by 1."}, {"q": "HCl at 298 K. Which J has the brightest teeth?", "a": "3", "w": ["0", "1", "10"], "why": "Shares 1, 2.71, 3.68, 3.79, 3.24."}, {"q": "Why does nitrogen let the ground’s glow through?", "a": "its stretch shifts no charge", "w": ["there is too little of it", "it is too heavy", "its bond is too stiff"], "why": "Two like atoms."}, {"q": "NO₂’s bond holds 300.5 kJ/mol. The longest wavelength that breaks it?", "a": "about 398 nm", "w": ["about 656 nm", "about 300 nm", "about 15 μm"], "why": "N_A hc / D."}, {"q": "Brighter red light on NO₂?", "a": "breaks nothing", "w": ["breaks it faster", "makes ozone", "breaks the N–O bond"], "why": "One lump breaks one bond."}];

(window.LADDER_CARDS["36·chem"]=window.LADDER_CARDS["36·chem"]||[]).push(...[{"q": "What is the energy of a mole of photons at 500 nm?", "a": "about 239 kJ", "w": ["about 0.0024 kJ", "about 500 kJ", "about 3.97 × 10⁻¹⁹ kJ"], "why": "N_A·hc/λ ≈ 0.1196/(5 × 10⁻⁷) J."}, {"q": "Can a photon of 500 nm break a C–C bond of 348 kJ per mole?", "a": "no: it would need λ ≤ about 344 nm", "w": ["yes, always", "yes, if the light is bright enough", "only in a mole of them"], "why": "The bond-breaking technique."}, {"q": "The bond-breaking technique says a 300 nm photon can break a C–C bond. Does it say it will?", "a": "no: only that it can", "w": ["yes", "yes, if the molecule is hot", "no: it never can"], "why": "Whether the molecule takes it is another matter."}, {"q": "A dye in white light takes away a band of hue θ. Which hue does it look?", "a": "opp(θ)", "w": ["θ", "θ + 90°", "grey"], "why": "The left-colour technique: white less the band."}, {"q": "A dye takes away orange near 600 nm. What colour does it look?", "a": "a blue", "w": ["orange", "a green", "white"], "why": "Across the circle from orange."}, {"q": "A molecule takes light at 490 nm and gives light back. Which could it give back?", "a": "515 nm", "w": ["450 nm", "490 nm and more energy", "only 490 nm"], "why": "The redder-return technique: λ₂ ≥ λ₁."}, {"q": "Yield 0.93, taken at 490 nm, given back at 515 nm. What share of the energy comes back?", "a": "about 0.885", "w": ["0.93", "1.05", "about 0.95"], "why": "φ·λ₁/λ₂."}, {"q": "Why does a highlighter look brighter than white paper?", "a": "it turns light the eye counts little into light it counts much", "w": ["it gives back more energy than it takes", "it is wet", "it sends back every wavelength more"], "why": "More seen light, not more energy."}, {"q": "Each held molecule lets go with chance k per second. How does the afterglow fall?", "a": "I₀e^(−kt), halving every ln 2/k", "w": ["by the same amount each second", "as 1/t", "not at all"], "why": "First-order (17·chem)."}, {"q": "A glow halves more and more slowly as it fades. What does that suggest?", "a": "traps of many depths, each with its own rate", "w": ["one chance per second for all", "the lamp is still on", "the glow is getting brighter"], "why": "The many-traps technique."}, {"q": "Light must bounce n times, keeping 0.3 each time. What leaves?", "a": "0.3ⁿ", "w": ["0.3n", "0.7ⁿ", "1 − 0.3n"], "why": "A share of a share, n times."}, {"q": "Why does a sparse forest of tubes send back so little from its top face?", "a": "it is nearly empty, so its index is near 1 and the face share near 0", "w": ["the tubes are black paint", "it is very cold", "it absorbs only ultraviolet"], "why": "((n − 1)/(n + 1))² ≈ 0."}]);
